  need.filter(r=>!r.long).forEach(r=>dOf(r.i).forEach(d=>{ if(imgs.length < 16){ imgs.push(d.b64); legend.push(`картинка ${imgs.length}: черновик к заданию ${r.num} (id ${r.i}), только для комментария`); } }));
